text:
{
 "title": "国立大学法人法の改正",
 "lead": {
  "es": "国立大学《こくりつだいがく》の運営《うんえい》のしくみを見直《みなお》し、北海道《ほっかいどう》と奈良《なら》の大学《だいがく》をまとめることなどを決《き》めた法律《ほうりつ》です。",
  "hs": "国立大学法人などの運営を改善するため、学長選考会議や｜監事《かんじ》のしくみを強め、北海道と奈良の国立大学法人を統合することなどを定めた法律です。",
  "std": "国立大学法人等の管理運営の改善と教育研究体制の整備・充実のため、学長選考会議・監事の機能強化や、国立大学法人の統合などを行う法律です。",
  "univ": "国立大学法人等の管理運営の改善並びに教育研究体制の整備及び充実等を図るため、学長選考会議の機能強化及び監事の体制強化のために必要な措置を講ずるとともに、国立大学法人の統合等の措置を講ずる法律。"
 },
 "facts": [
  {
   "es": "大学《だいがく》の中期計画《ちゅうきけいかく》に、目標《もくひょう》にむけた取《と》り組《く》みがどれだけ進《すす》んだかをはかる目安《めやす》を書《か》きます。毎年度《まいねんど》の計画《けいかく》と評価《ひょうか》はやめます。",
   "hs": "国立大学法人などの中期計画に、目標達成のための取り組みの進み具合をはかる指標を加え、年度計画と年度ごとの評価をやめる。",
   "std": "国立大学法人等の中期計画の記載事項に、目標達成のための措置の実施状況に関する指標を追加し、年度計画と年度評価を廃止します。",
   "univ": "国立大学法人等が作成する中期計画の記載事項に、教育研究の質の向上及び業務運営の改善・効率化に関する目標を達成するためとるべき措置の実施状況に関する指標を追加するとともに、中期計画に基づく業務運営に関する年度計画及び業務の実績等に関する年度評価を廃止する。"
  },
  {
   "es": "学長《がくちょう》をえらぶ会議《かいぎ》の名前《なまえ》を「学長選考《がくちょうせんこう》・監察会議《かんさつかいぎ》」にし、学長《がくちょう》は委員《いいん》になれません。大学《だいがく》をチェックする監事《かんじ》のうち1人《ひとり》以上《いじょう》は毎日《まいにち》つとめる人《ひと》にし、学長《がくちょう》の不正《ふせい》などに気《き》づいたら会議《かいぎ》に報告《ほうこく》します。",
   "hs": "学長選考会議の名前を「学長選考・｜監察《かんさつ》会議」にし、学長は委員になれず、理事は教育研究評議会でえらばれた人だけが委員になれる。｜監事《かんじ》のうち少なくとも1人は常勤とし、｜監事《かんじ》は学長に不正や法令｜違反《いはん》などがあると認めるときは、会議に報告しなければならない。大学共同利用機関法人も同じにする。",
   "std": "学長選考会議の名称を「学長選考・監察会議」とし、学長を委員に加えられないこと、理事は教育研究評議会で選出された者のみ委員になれることとします。監事のうち少なくとも1人を常勤とし、監事は学長に不正行為や法令違反等があると認めるときは同会議に報告しなければなりません。大学共同利用機関法人も同様です。",
   "univ": "国立大学法人の学長選考会議の名称を「学長選考・監察会議」とするとともに、同会議の委員に学長を加えることができないこととし、理事は教育研究評議会において選出された者のみが委員になることができることとする。監事のうち少なくとも1人は常勤とするとともに、監事は学長に不正行為や法令違反等があると認めるときは、同会議に報告しなければならない。大学共同利用機関法人についても同様の措置を講ずる。"
  },
  {
   "es": "特別《とくべつ》に指定《してい》された国立大学《こくりつだいがく》は、理事《りじ》を2人《ふたり》までふやせます。",
   "hs": "指定国立大学法人などの理事は、2人まで増やせる。",
   "std": "指定国立大学法人又は指定国立大学を設置する国立大学法人の理事は、2人まで増員できます。",
   "univ": "指定国立大学法人又は指定国立大学を設置する国立大学法人の理事は、2人まで増員できることとする。"
  },
  {
   "es": "国立大学《こくりつだいがく》は、文部科学大臣《もんぶかがくだいじん》にみとめられれば、大学《だいがく》の施設《しせつ》をほかの大学《だいがく》に使《つか》ってもらう仕事《しごと》や、研究《けんきゅう》の成果《せいか》を使《つか》う仕事《しごと》をする会社《かいしゃ》にお金《かね》を出《だ》せます。特別《とくべつ》に指定《してい》された大学《だいがく》は、研究《けんきゅう》の成果《せいか》で商品《しょうひん》をつくる会社《かいしゃ》などにもお金《かね》を出《だ》せます。",
   "hs": "国立大学法人などは、文部科学大臣の認可を受けて、｜施設《しせつ》・設備の管理やほかの大学などによる利用をすすめる事業をする者や、研究成果を使う政令で定める事業をする者に、出資できる。指定国立大学法人は、研究成果を使って商品の開発・生産などをする者にも、認可を受けて出資できる。",
   "std": "国立大学法人等は、文部科学大臣の認可を受けて、保有する教育研究施設・設備等の管理や他大学等による利用の促進の事業を行う者、研究成果を活用する政令で定める事業を行う者に出資できます。指定国立大学法人は、研究成果を活用して商品の開発・生産等を行う者にも、認可を受けて出資できます。",
   "univ": "国立大学法人等は、当該国立大学法人等が保有する教育研究に係る施設、設備等の管理及び他の大学等による利用の促進に係る事業を実施する者並びに研究成果を活用する事業であって政令で定めるものを実施する者に対し、文部科学大臣の認可を受けて、出資を行うことができる。指定国立大学法人については、その研究成果を活用して商品の開発・生産等を行う事業を実施する者に対し、文部科学大臣の認可を受けて、出資を行うことができる。"
  },
  {
   "es": "小樽商科大学《おたるしょうかだいがく》・帯広畜産大学《おびひろちくさんだいがく》・北見工業大学《きたみこうぎょうだいがく》をまとめて「国立大学法人北海道国立大学機構《こくりつだいがくほうじんほっかいどうこくりつだいがくきこう》」にします。奈良教育大学《ならきょういくだいがく》と奈良女子大学《ならじょしだいがく》をまとめて「国立大学法人奈良国立大学機構《こくりつだいがくほうじんならこくりつだいがくきこう》」にします。",
   "hs": "国立大学法人｜小樽《おたる》商科大学と国立大学法人北見工業大学を国立大学法人帯広｜畜産《ちくさん》大学に統合し、3大学を置く「国立大学法人北海道国立大学機構」とする。国立大学法人奈良教育大学を国立大学法人奈良女子大学に統合し、2大学を置く「国立大学法人奈良国立大学機構」とする。",
   "std": "国立大学法人小樽商科大学と国立大学法人北見工業大学を国立大学法人帯広畜産大学に統合し、3大学を設置する国立大学法人北海道国立大学機構とします。国立大学法人奈良教育大学を国立大学法人奈良女子大学に統合し、2大学を設置する国立大学法人奈良国立大学機構とします。",
   "univ": "国立大学法人小樽商科大学及び国立大学法人北見工業大学を国立大学法人帯広畜産大学に統合し、以上3大学を設置する国立大学法人北海道国立大学機構とする。国立大学法人奈良教育大学を国立大学法人奈良女子大学に統合し、以上2大学を設置する国立大学法人奈良国立大学機構とする。"
  },
  {
   "es": "この法律《ほうりつ》は、一部《いちぶ》をのぞき、令和《れいわ》4年《ねん》4月《がつ》1日《ついたち》から使《つか》われます。",
   "hs": "この法律は、一部をのぞき、令和4年4月1日から｜施行《しこう》する。",
   "std": "一部を除き、令和4年4月1日から施行します。",
   "univ": "この法律は、一部を除き、令和4年4月1日から施行する。"
  }
 ]
}
